"""Offline scene validation using the exact shared aiTrends player (no model/API calls)."""
from pathlib import Path
import argparse,subprocess,json
P=Path(__file__).resolve().parents[1];ROOT=P.parents[1];a=argparse.ArgumentParser();a.add_argument('--work',type=Path,required=True);args=a.parse_args();args.work.mkdir(parents=True,exist_ok=True)
s=(ROOT/'skill/scripts/render.mjs').read_text().split('async function renderVideo()')[0]
s=s.replace("const KIT = fileURLToPath(new URL('../../aitrends-2d-studio/skills/make-2d-video/kit/', import.meta.url));",'const KIT = '+json.dumps(str(ROOT/'aitrends-2d-studio/skills/make-2d-video/kit'))+';')
s+='''
const browser=await chromium.launch(LAUNCH),page=await openPlayer(browser),story=JSON.parse(fs.readFileSync(path.join(PROJECT,'story/shots.json'))),records=[];
for(const sh of story.shots){const sec=(sh.start+sh.end)/2;await page.evaluate(f=>window.renderFrame(f),Math.floor(sec*24));const r=await page.evaluate(async({cam})=>{const st=(await import('/project/scenes/world.js')).current,H=st.H,m=st.motion,id=cam==='reverse'?'lia':'nico',a=st.A[id],head=a.head.getWorldPosition(new H.Vector3()),front=new H.Vector3(1,0,0).applyQuaternion(a.head.getWorldQuaternion(new H.Quaternion())),dot=front.dot(st.camera.position.clone().sub(head).normalize());const n=m.A.nico,feet=Object.values(st.A.nico.feet).map(v=>v.getWorldPosition(new H.Vector3()).y-.065),footError=Math.min(...feet)-(n.y||0);return {errors:window.ERRORS,face_dot:dot,camera:st.camera.position.toArray(),head:head.toArray(),feet,foot_ground_error:n.moving?footError:null,action:m.act,object:m.object,hand:st.A.nico.point().toArray()};},{cam:sh.params.cam});records.push({shot:sh.id,beat:sh.params.beat+1,cam:sh.params.cam,seconds:sec,...r});}
const errors=records.flatMap(x=>x.errors),badFaces=records.filter(x=>['close','reverse'].includes(x.cam)&&x.face_dot<.4),badFeet=records.filter(x=>x.foot_ground_error!==null&&Math.abs(x.foot_ground_error)>.025),nan=records.filter(x=>[...x.camera,...x.head,...x.hand].some(v=>!Number.isFinite(v)));const result={sampled_shots:records.length,player_errors:[...new Set(errors)],bad_front_face_shots:badFaces.map(x=>x.shot),bad_ground_contacts:badFeet.map(x=>x.shot),nonfinite_values:nan.length,records,limitations:'Sampled geometry/framing, not human review of every motion frame or listening.'};fs.writeFileSync(path.join(PROJECT,'qa/scene-numeric-audit.json'),JSON.stringify(result,null,2)+'\\n');await browser.close();server.close();if(errors.length||badFaces.length||badFeet.length||nan.length)process.exitCode=1;console.log(JSON.stringify({shots:records.length,errors:errors.length,badFaces:badFaces.length,badFeet:badFeet.length,nan:nan.length}));
'''
runner=args.work/'scene-audit-runner.mjs';runner.write_text(s);subprocess.run(['node',str(runner),'--project',str(P),'--scale','0.25'],check=True)
